<template>
  <div class="formulario-container">
    <fieldset class="formulario">
      <legend>Gestión de Información del Empleado</legend>

      <form @submit.prevent="guardar">
        <div class="grupo">
          <label for="documento">Documento de Identidad</label>
          <input 
            type="text" 
            id="documento" 
            v-model="documento" 
            placeholder="Ej: 1018234567" 
            required 
          />
        </div>

        <div class="grupo">
          <label for="nombre">Nombre Completo</label>
          <input 
            type="text" 
            id="nombre" 
            v-model="nombre" 
            placeholder="Ej: Diego Rojas" 
            required 
          />
        </div>

        <div class="grupo-doble">
          <div class="grupo">
            <label for="usuario">Usuario</label>
            <input 
              type="text" 
              id="usuario" 
              v-model="usuario" 
              placeholder="Ej: drojas" 
              required 
            />
          </div>
          <div class="grupo">
            <label for="contrasena">Contraseña</label>
            <input 
              type="password" 
              id="contrasena" 
              v-model="contrasena" 
              placeholder="••••••••" 
              required 
            />
          </div>
        </div>

        <div class="grupo-doble">
          <div class="grupo">
            <label for="cargo">Cargo</label>
            <input 
              type="text" 
              id="cargo" 
              v-model="cargo" 
              placeholder="Ej: Desarrollador Backend" 
              required 
            />
          </div>
          <div class="grupo">
            <label for="edad">Edad</label>
            <input 
              type="number" 
              id="edad" 
              v-model.number="edad" 
              placeholder="Ej: 25" 
              required 
            />
          </div>
        </div>

        <div class="grupo-doble">
          <div class="grupo">
            <label for="telefono">Teléfono</label>
            <input 
              type="text" 
              id="telefono" 
              v-model="telefono" 
              placeholder="Ej: 3001234567" 
              required 
            />
          </div>
          <div class="grupo">
            <label for="tipoSangre">Tipo de Sangre</label>
            <select id="tipoSangre" v-model="tipoSangre" required>
              <option value="" disabled selected>Seleccione</option>
              <option value="O+">O+</option>
              <option value="O-">O-</option>
              <option value="A+">A+</option>
              <option value="A-">A-</option>
              <option value="B+">B+</option>
              <option value="B-">B-</option>
              <option value="AB+">AB+</option>
              <option value="AB-">AB-</option>
            </select>
          </div>
        </div>

        <div class="grupo">
          <label for="direccion">Dirección de Residencia</label>
          <input 
            type="text" 
            id="direccion" 
            v-model="direccion" 
            placeholder="Ej: Calle 45 # 12-34" 
            required 
          />
        </div>

        <div class="boton-principal">
          <button type="submit" class="btn-guardar">Registrar / Guardar Empleado</button>
        </div>

        <hr class="divisor" />

        <div class="seccion-busqueda">
          <p class="instruccion-id">Para consultar, actualizar o eliminar, ingrese el ID (Clave primaria):</p>
          
          <div class="grupo grupo-id">
            <label for="idEmpleado">ID de Empleado</label>
            <input 
              type="number" 
              id="idEmpleado" 
              v-model.number="idEmpleado" 
              placeholder="Ej: 1, 2, 3..." 
            />
          </div>

          <div class="botones-operaciones">
            <button type="button" class="btn-consultar" @click="consultar">Consultar</button>
            <button type="button" class="btn-actualizar" @click="actualizar">Actualizar</button>
            <button type="button" class="btn-eliminar" @click="eliminar">Eliminar</button>
          </div>
        </div>

      </form>
    </fieldset>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  name: "FormularioEmpleados",
  data() {
    return {
      idEmpleado: null,
      documento: '',
      usuario: '',
      contrasena: '',
      nombre: '',
      direccion: '',
      edad: null,
      cargo: '',
      tipoSangre: '',
      telefono: ''
    };
  },
  methods: {
    guardar() {
      const empleadoObj = {
        documento: this.documento,
        usuario: this.usuario,
        contrasena: this.contrasena,
        nombre: this.nombre,
        direccion: this.direccion,
        edad: this.edad,
        cargo: this.cargo,
        tipoSangre: this.tipoSangre,
        telefono: this.telefono
      };

      axios.post("https://proyecto-production-8262.up.railway.app/api/empleados", empleadoObj)
      .then(response => {
        console.log("Empleado guardado:", response.data);
        alert("Empleado registrado con éxito");
        this.limpiarFormulario();
        this.$emit('actualizarTabla');
      })
      .catch(error => {
        console.error("Error al registrar empleado:", error);
        alert("Error al registrar el empleado");
      });
    },


    consultar() {
      if (!this.idEmpleado) {
        alert("Por favor ingrese un ID válido para consultar");
        return;
      }
      axios.get(`https://proyecto-production-8262.up.railway.app/api/empleados/${this.idEmpleado}`)
      .then(response => {
        const data = response.data;
        if (data) {
          this.documento = data.documento;
          this.usuario = data.usuario;
          this.contrasena = data.contrasena;
          this.nombre = data.nombre;
          this.direccion = data.direccion;
          this.edad = data.edad;
          this.cargo = data.cargo;
          this.tipoSangre = data.tipoSangre;
          this.telefono = data.telefono;
        } else {
          alert("No se encontró ningún empleado con ese ID");
        }
      })
      .catch(error => {
        console.error("Error al consultar empleado:", error);
        alert("Consulta fallida / Empleado no encontrado");
      });
    },

    actualizar() {
      if (!this.idEmpleado) {
        alert("Por favor ingrese un ID para actualizar");
        return;
      }

      const empleadoObj = {
        idEmpleado: this.idEmpleado,
        documento: this.documento,
        usuario: this.usuario,
        contrasena: this.contrasena,
        nombre: this.nombre,
        direccion: this.direccion,
        edad: this.edad,
        cargo: this.cargo,
        tipoSangre: this.tipoSangre,
        telefono: this.telefono
      };

      axios.put(`https://proyecto-production-8262.up.railway.app/api/empleados/actualizar/${this.idEmpleado}`, empleadoObj)
      .then(response => {
        console.log("Empleado actualizado:", response.data);
        alert("Información del empleado actualizada con éxito");
        this.limpiarFormulario();
        this.$emit('actualizarTabla');
      })
      .catch(error => {
        console.error("Error al actualizar empleado:", error);
        alert("Actualización fallida");
      });
    },

    eliminar() {
      if (!this.idEmpleado) {
        alert("Por favor ingrese un ID para eliminar");
        return;
      }
      axios.delete(`https://proyecto-production-8262.up.railway.app/api/empleados/${this.idEmpleado}`)
      .then(() => {
        alert("Empleado eliminado con éxito");
        this.limpiarFormulario();
        this.$emit('actualizarTabla');
      })
      .catch(error => {
        console.error("Error al eliminar empleado:", error);
        alert("Eliminación fallida");
      });
    },

    limpiarFormulario() {
      this.idEmpleado = null;
      this.documento = '';
      this.usuario = '';
      this.contrasena = '';
      this.nombre = '';
      this.direccion = '';
      this.edad = null;
      this.cargo = '';
      this.tipoSangre = '';
      this.telefono = '';
    }
  }
};
</script>

<style scoped>
.formulario-container {
  width: 100%;
}

.formulario {
  border: 2px solid #C8D8EE;
  border-radius: 8px;
  padding: 22px 28px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}

.formulario legend {
  padding: 0 10px;
  color: #293A63;
  font-weight: bold;
  font-size: 1.1rem;
}

.grupo {
  display: flex;
  flex-direction: column;
  margin-bottom: 14px;
}

.grupo-doble {
  display: flex;
  gap: 15px;
}

.grupo-doble .grupo {
  flex: 1;
}

.grupo label {
  margin-bottom: 5px;
  color: #293A63;
  font-weight: 500;
  font-size: 13px;
}

.grupo input,
.grupo select {
  padding: 9px 12px;
  border: 1px solid #D8D8D8;
  border-radius: 8px;
  font-size: 14px;
  outline: none;
}

.boton-principal {
  margin-top: 10px;
}

.btn-guardar {
  width: 100%;
  padding: 11px;
  border: none;
  border-radius: 30px;
  background: #2F88C1;
  color: white;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.3s;
}

.btn-guardar:hover {
  background: #246C97;
}

.divisor {
  border: none;
  border-top: 1px dashed #C8D8EE;
  margin: 20px 0;
}

.seccion-busqueda {
  background-color: #F8FAFC;
  padding: 14px;
  border-radius: 8px;
  border: 1px solid #E2E8F0;
}

.instruccion-id {
  font-size: 12px;
  color: #293A63;
  margin-bottom: 8px;
  font-weight: 600;
  text-align: center;
}

.grupo-id input {
  border: 1px solid #2F88C1;
  background-color: #ffffff;
}

.botones-operaciones {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.botones-operaciones button {
  flex: 1;
  padding: 9px 5px;
  border: none;
  border-radius: 20px;
  color: white;
  font-weight: bold;
  font-size: 12px;
  cursor: pointer;
  transition: opacity 0.3s;
}

.btn-consultar { background-color: #F39C12; }
.btn-actualizar { background-color: #27AE60; }
.btn-eliminar { background-color: #E74C3C; }

.botones-operaciones button:hover {
  opacity: 0.9;
}
</style>