<template>
  <div class="tabla-container">
    <h2>Listado de Empleados</h2>

    <div class="tabla-responsive">
      <table class="tabla-empleados">
        <thead>
          <tr>
            <th>ID</th>
            <th>Documento</th>
            <th>Nombre</th>
            <th>Usuario</th>
            <th>Cargo</th>
            <th>Edad</th>
            <th>Teléfono</th>
            <th>T. Sangre</th>
            <th>Dirección</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="emp in empleados" :key="emp.idEmpleado">
            <td>{{ emp.idEmpleado }}</td>
            <td>{{ emp.documento }}</td>
            <td>{{ emp.nombre }}</td>
            <td>{{ emp.usuario }}</td>
            <td>{{ emp.cargo }}</td>
            <td>{{ emp.edad }}</td>
            <td>{{ emp.telefono }}</td>
            <td>{{ emp.tipoSangre }}</td>
            <td>{{ emp.direccion }}</td>
          </tr>
          <tr v-if="empleados.length === 0">
            <td colspan="9" class="tabla-vacia">No hay empleados registrados en la base de datos</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  name: "TablaEmpleados",
  data() {
    return {
      empleados: []
    };
  },
  mounted() {
    this.obtenerEmpleados();
  },
  methods: {
    obtenerEmpleados() {
      axios.get("https://proyecto-production-8262.up.railway.app/api/empleados/listar")
      .then(response => {
        this.empleados = response.data;
      })
      .catch(error => {
        console.error("Error al listar empleados:", error);
      });
    }
  }
};
</script>

<style scoped>
.tabla-container {
  width: 100%;
  border: 2px solid #C8D8EE;
  border-radius: 8px;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}

.tabla-container h2 {
  color: #293A63;
  margin-bottom: 15px;
  font-size: 1.3rem;
  text-align: center;
}

.tabla-responsive {
  overflow-x: auto;
}

.tabla-empleados {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.tabla-empleados th,
.tabla-empleados td {
  border: 1px solid #D8E5F2;
  padding: 8px 10px;
  text-align: left;
}

.tabla-empleados th {
  background-color: #2F88C1;
  color: white;
  font-weight: bold;
  white-space: nowrap;
}

.tabla-empleados tr:nth-child(even) {
  background-color: #F8FAFC;
}

.tabla-vacia {
  text-align: center;
  color: #888;
  font-style: italic;
  padding: 20px;
}
</style>